comments:
/* ===== Ins / Instagram · 评述模块（白底一体，分割线分隔） ===== */
.be-comments {
  background: #ffffff;
  border-top: 1px solid #efefef;
  /* 评论渲染在卡片内部，通栏贴边（抵消卡片 padding 190px 12px 35px），与卡片共用边框圆角阴影，真正一体 */
  margin: 0 -12px -35px !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.be-comment {
  display: flex;
  gap: 10px;
  padding: 11px 12px;
  border-bottom: 1px solid #f5f5f5;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #f2f2f2;
  border: 1px solid #efefef;
  flex-shrink: 0;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 6px; }
.be-comment-name { font-size: 13px; font-weight: 600; color: #262626; }
.be-comment-id { font-size: 12px; color: #8e8e8e; }
.be-comment-time { font-size: 12px; color: #8e8e8e; }
.be-comment-text { font-size: 13px; color: #262626; line-height: 1.55; margin-top: 2px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #c13584; }
